def area(kind, size):
    if kind == 'square':
        return size * size
    elif kind == 'circle':
        return 3.14159 * size * size
    elif kind == 'triangle':
        return 0.5 * size * size
    else:
        raise ValueError('unknown shape: ' + kind)

